; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the ROM NTC CPCFW (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_turbo_on:	jp 5
kw_turbo_off:	jp 7
kw_goto_iffalse:	jp 10
kw_goto_iffalse_n:	jp 11
kw_goto_ifzero_n:	jp 15
kw_next1l_n:	jp 31
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_ftov:		jp 50
kw_inc:		jp 51
kw_add:		jp 53
kw_addl:		jp 54
kw_subvv:	jp 55
kw_divlv:	jp 65
kw_negv:		jp 69
kw_andvv:	jp 72
kw_andvl:	jp 73
kw_orvv:		jp 74
kw_notv:		jp 78
kw_scpltvl:	jp 80
kw_scpgtvl:	jp 84
kw_scpgevl:	jp 86
kw_cpeqvl:	jp 96
kw_cpnevl:	jp 98
kw_aset:		jp 112
kw_strcpy:	jp 122
kw_strcmpeq:	jp 126
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inkeys:	jp 145
kw_locatell:	jp 148
kw_model:	jp 150
kw_modev:	jp 151
kw_frame:	jp 152
kw_ticks:	jp 154
kw_strucase:	jp 180
kw_strasc:	jp 185
kw_strval:	jp 186
mem_go:		jp 245
mem_sel:		jp 258
mem_allocpage:	jp 266
ntc_ovl_enter:	jp 276
gfx_line:	jp 283
gfx_flip:	jp 284
gfx_double:	jp 285
gfx_copyrows:	jp 286
kw_bssinit:	jp 288
gfx_begin:	jp 327
gfx_end:		jp 328
NTC_RJ_N	equ 53		; entries
gfx_base	equ #8917		; ROM data
gfx_dbl	equ #8918		; ROM data
gfx_sp	equ #891A		; ROM data
gfx_x0	equ #8907		; ROM data
gfx_x1	equ #890B		; ROM data
gfx_y0	equ #8909		; ROM data
gfx_y1	equ #890D		; ROM data
mem_a1	equ #884F		; ROM data
mem_res	equ #8855		; ROM data
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8807		; ROM data
ntc_ovl_lc	equ #8897		; ROM data
ntc_smode	equ #8924		; ROM data
ntc_v_free	equ #895E		; ROM data
ntc_v_romen	equ #8964		; ROM data
ntc_v_romold	equ #8966		; ROM data
ntc_v_stamp	equ #8962		; ROM data
ntc_v_start	equ #8960		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, NTC_STAMP
			ld (ntc_v_stamp), hl
			ld a, 1
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "ROM NTC CPCFW (NTCFW.ROM) not found", 0
ntc_rj_tlk:		db "ROM NTC CPCFW too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

; pages (Option Page / Option Class Overlay): the RAM page each is loaded in (0 = not loaded),
